/// <reference types="vitest/config" />
import { fileURLToPath, URL } from 'node:url'
import react from '@vitejs/plugin-react'
import { tanstackRouter } from '@tanstack/router-plugin/vite'
import { defineConfig } from 'vite'

// The API the dev server forwards /api to. E2E runs its own API on another port and overrides this.
const apiTarget = process.env.VITE_PROXY_TARGET ?? 'http://localhost:5100'

export default defineConfig({
  // The route tree is generated by dev/build and committed, so tests don't need the generator.
  plugins: [...(process.env.VITEST ? [] : [tanstackRouter({ target: 'react', autoCodeSplitting: false })]), react()],
  server: {
    // Same-origin API calls in dev; no CORS needed.
    proxy: { '/api': apiTarget, '/health': apiTarget },
  },
  resolve: {
    alias: { '@': fileURLToPath(new URL('./src', import.meta.url)) },
    // @aurigo/react-core-component-dev hard-pins its own React 18, which npm would nest privately.
    // The package.json "overrides" entry forces it onto this app's React 19; dedupe is the Vite-side
    // backstop so two copies of React can never be bundled (that renders as "older version of React").
    dedupe: ['react', 'react-dom'],
  },
  test: {
    environment: 'jsdom',
    setupFiles: ['./src/test/setup.ts'],
    globals: true, // lets Testing Library auto-clean the DOM between tests
    pool: 'threads',
    // Each worker loads the whole component library (~1 GB). Unbounded parallelism on a busy machine made workers
    // time out while starting; a small cap (2) keeps the run reliable; a start timeout is a fixed 60 s, so a memory-starved machine failed whole files, which matters more than shaving seconds.
    maxWorkers: 2,
    testTimeout: 60_000,
  },
})
